System.out.println("=== AND ===");
print(stmt.executeQuery(
        "SELECT name, category, price FROM products WHERE category = 'Peryferia' AND price > 100"));

System.out.println("\n=== OR ===");
print(stmt.executeQuery(
        "SELECT name, category FROM products WHERE category = 'Komputery' OR price < 20"));

System.out.println("\n=== NOT ===");
print(stmt.executeQuery(
        "SELECT name, category FROM products WHERE NOT category = 'Peryferia'"));
// AND - oba warunki musza byc prawdziwe. OR - wystarczy jeden. NOT - zaprzecza warunkowi.
// Kolejnosc laczenia warunkow warto kontrolowac nawiasami - AND ma wyzszy priorytet niz OR.

System.out.println("=== LIKE (nazwy zaczynajace sie na 'K') ===");
print(stmt.executeQuery("SELECT name FROM products WHERE name LIKE 'K%'"));
// % = dowolny ciag znakow (rowniez pusty), _ = dokladnie jeden dowolny znak
// LIKE jest domyslnie CASE-SENSITIVE.

System.out.println("\n=== ILIKE (H2 wspiera, ale to NIE jest standard SQL) ===");
print(stmt.executeQuery("SELECT name FROM products WHERE name ILIKE '%LAPTOP%'"));
// UWAGA PRZENOSNOSC: ILIKE pochodzi z PostgreSQL, wiekszosc silnikow go nie zna.
// Przenosny odpowiednik: WHERE LOWER(name) LIKE LOWER('%laptop%')

System.out.println("=== BETWEEN (cena 50-900) ===");
print(stmt.executeQuery("SELECT name, price FROM products WHERE price BETWEEN 50 AND 900"));
// x BETWEEN a AND b jest rownowazne x >= a AND x <= b - OBIE granice WLACZONE.

System.out.println("\n=== IN ===");
print(stmt.executeQuery("SELECT name FROM products WHERE id IN (1, 4, 6)"));
// x IN (a, b, c) jest rownowazne x = a OR x = b OR x = c, ale krocej i czytelniej.

System.out.println("=== EXISTS (produkty, ktore maja zamowienie) ===");
print(stmt.executeQuery("""
    SELECT p.name
    FROM products p
    WHERE EXISTS (SELECT 1 FROM orders o WHERE o.product_id = p.id)
    """));

System.out.println("\n=== IS NULL (produkty bez opisu) ===");
print(stmt.executeQuery("SELECT name FROM products WHERE description IS NULL"));
// NULL oznacza 'brak wartosci' - NIE MOZNA go porownywac operatorem =
// (warunek x = NULL nigdy nie jest prawdziwy!). Uzywaj IS NULL / IS NOT NULL.
